import React from 'react';

export function InvoiceList({ load }) {
  const [rows, setRows] = React.useState([]);
  const mountedRef = React.useRef(true);
  React.useEffect(() => () => {
    mountedRef.current = false;
  }, []);
  const refresh = () => load().then((r) => {
    if (!mountedRef.current) return;
    setRows(r);
  });
  return <ul onClick={refresh}>{rows.map((r) => <li key={r.id}>{r.name}</li>)}</ul>;
}

import { useCallback, useEffect, useRef, useState } from 'react';

export function useSaveDraft(save: (text: string) => Promise<void>) {
  const [saving, setSaving] = useState(false);
  const componentIsMounted = useRef<boolean>(true);
  useEffect(function track() {
    return function cleanup() {
      componentIsMounted.current = false;
    };
  }, []);
  return useCallback(async (text: string) => {
    setSaving(true);
    await save(text);
    if (componentIsMounted.current) setSaving(false);
  }, [save, saving]);
}

import * as React from 'react';

export const Resizer = ({ onSize }: { onSize: (w: number) => void }) => {
  const unmounted = React.useRef(true);
  const node = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const observer = new ResizeObserver(() => {
      if (unmounted.current) onSize(node.current!.clientWidth);
    });
    observer.observe(node.current!);
    return () => {
      observer.disconnect();
      if (unmounted.current) {
        unmounted.current = false;
      }
    };
  }, [onSize]);
  return <div ref={node} />;
};

import { useEffect as useMountEffect, useRef as useR } from 'react';

export default function Feed({ poll }: { poll: () => Promise<void> }) {
  const isMountedRef = useR(true);
  useMountEffect(() => (() => { isMountedRef.current = false; }), []);
  const tick = () => poll().then(() => { if (isMountedRef.current) tick(); });
  return <section onClick={tick} />;
}

import { useEffect, useRef, useState } from 'react';

export function usePolling(load) {
  const [data, setData] = useState(null);
  const busyRef = useRef(false);
  const wasMounted = useRef(true);
  useEffect(() => {
    return () => {
      wasMounted.current = false;
    };
  }, []);
  const poll = async () => {
    busyRef.current = true;
    const next = await load();
    busyRef.current = false;
    if (wasMounted.current) setData(next);
  };
  return [data, poll];
}

