export function Tabs({ lazy, load }: { lazy: boolean; load: () => Promise<void> }) {
  const isMountedRef = React.useRef(true);
  React.useEffect(() => (lazy ? undefined : () => {
    isMountedRef.current = false;
  }), [lazy]);
  return <nav onClick={() => load().then(() => isMountedRef.current && load())} />;
}

import { useEffect, useRef } from 'react';

export const Ticker = ({ tick }: { tick: () => void }) => {
  const mounted = useRef(true);
  useEffect(() => {
    const id = setInterval(() => mounted.current && tick(), 1000);
    return () => {
      clearInterval(id);
      mounted.current = false;
    };
  }, [mounted, tick]);
  return null;
};

